"""
Pydantic schemas for the Skills service.

"""

from datetime import datetime
from enum import Enum
from typing import Any, Optional

from pydantic import BaseModel, ConfigDict, Field, model_validator


class ReviewStatus(str, Enum):
    """Skill review status for publishing."""

    NONE = "NONE"
    REQUESTED = "REQUESTED"
    PENDING = "PENDING"
    APPROVED = "APPROVED"
    DENIED = "DENIED"


class RemoteCreateStatus(str, Enum):
    """Skill upload status."""

    PENDING = "PENDING"
    COMPLETE = "COMPLETE"


class Visibility(str, Enum):
    """Skill visibility level."""

    PRIVATE = "private"
    PUBLIC = "public"
    SHARED = "shared"


class SharedUser(BaseModel):
    """User with shared access to a skill."""

    id: Optional[str] = Field(default=None, alias="_id")
    email: str
    name: Optional[str] = None

    model_config = ConfigDict(populate_by_name=True)


class OwnerInfo(BaseModel):
    """Populated owner information returned in some responses."""

    id: Optional[str] = Field(default=None, alias="_id")
    email: Optional[str] = None
    name: Optional[str] = None

    model_config = ConfigDict(populate_by_name=True)


class Skill(BaseModel):
    """Represents a qBraid skill."""

    slug: str = Field(..., description="Unique skill identifier (URL-safe)")
    name: str = Field(..., description="Display name of the skill")
    description: Optional[str] = Field(default=None, description="Skill description")
    version: str = Field(default="1.0.0", description="Skill version")
    owner: Optional[str] = Field(default=None, description="Owner user ID")
    owner_info: Optional[OwnerInfo] = Field(
        default=None, description="Populated owner info (from pending-reviews)"
    )
    owner_email: Optional[str] = Field(default=None, alias="ownerEmail")
    app_id: Optional[str] = Field(default=None, alias="appId", description="Linked app ID")
    tags: list[str] = Field(default_factory=list, description="Searchable tags")
    compatibility: list[str] = Field(default_factory=list, description="Platform compatibility")
    download_count: int = Field(default=0, alias="downloadCount")
    visibility: Visibility = Field(default=Visibility.PRIVATE)
    review_status: ReviewStatus = Field(default=ReviewStatus.NONE, alias="reviewStatus")
    remote_create_status: Optional[RemoteCreateStatus] = Field(
        default=None, alias="remoteCreateStatus"
    )
    checksum: Optional[str] = Field(default=None, description="SHA256 checksum")
    created_at: Optional[datetime] = Field(default=None, alias="createdAt")
    updated_at: Optional[datetime] = Field(default=None, alias="updatedAt")

    # Sharing fields (only visible to owner)
    read_access_users: Optional[list[str]] = Field(default=None, alias="readAccessUsers")
    write_access_users: Optional[list[str]] = Field(default=None, alias="writeAccessUsers")
    access_key: Optional[str] = Field(default=None, alias="accessKey")

    @model_validator(mode="before")
    @classmethod
    def handle_populated_owner(cls, data: Any) -> Any:
        """Handle owner field that can be either a string ID or populated object."""
        if not isinstance(data, dict):
            return data

        owner = data.get("owner")
        if owner is not None and isinstance(owner, dict):
            # Extract owner ID and store full info
            owner_id = owner.get("_id") or owner.get("id")
            data["owner"] = owner_id
            data["owner_info"] = owner
            # Also extract email if not already set
            if not data.get("ownerEmail") and owner.get("email"):
                data["ownerEmail"] = owner.get("email")

        return data

    model_config = ConfigDict(populate_by_name=True)


class SkillDownload(BaseModel):
    """Response from skill download endpoint."""

    slug: str
    download_url: str = Field(..., alias="downloadUrl")
    download_url_expires: int = Field(..., alias="downloadUrlExpires")
    checksum: Optional[str] = None

    model_config = ConfigDict(populate_by_name=True)


class SkillUpload(BaseModel):
    """Response from skill upload URL endpoint."""

    slug: str
    upload_url: str = Field(..., alias="uploadUrl")
    upload_url_expires: int = Field(..., alias="uploadUrlExpires")

    model_config = ConfigDict(populate_by_name=True)


class SkillCreateResponse(BaseModel):
    """Response from skill creation."""

    skill: Skill
    upload_url: str = Field(..., alias="uploadUrl")
    upload_url_expires: int = Field(..., alias="uploadUrlExpires")

    model_config = ConfigDict(populate_by_name=True)


class SkillCreateRequest(BaseModel):
    """Request to create a new skill."""

    name: str = Field(..., description="Display name (1-100 chars)")
    description: Optional[str] = Field(default=None, description="Max 500 chars")
    version: str = Field(default="1.0.0")
    tags: Optional[list[str]] = Field(default=None)
    compatibility: Optional[list[str]] = Field(default=None)
    app_id: Optional[str] = Field(default=None, alias="appId")
    visibility: Visibility = Field(default=Visibility.PRIVATE)

    model_config = ConfigDict(populate_by_name=True)


class ShareTarget(str, Enum):
    """Target type for sharing."""

    USER = "user"
    ORGANIZATION = "organization"


class ShareRequest(BaseModel):
    """Request to share a skill."""

    target_type: ShareTarget = Field(..., alias="targetType")
    email: Optional[str] = Field(default=None, description="Required if targetType is user")
    organization_id: Optional[str] = Field(
        default=None, alias="organizationId", description="Required if targetType is organization"
    )
    permissions: list[str] = Field(..., description="['read'] and/or ['write']")

    model_config = ConfigDict(populate_by_name=True)


class SharedWithResponse(BaseModel):
    """Response from shared-with endpoint."""

    skill: str
    read_access_users: list[SharedUser] = Field(default_factory=list, alias="readAccessUsers")
    write_access_users: list[SharedUser] = Field(default_factory=list, alias="writeAccessUsers")

    model_config = ConfigDict(populate_by_name=True)


class ShareCodeResponse(BaseModel):
    """Response from share code generation."""

    code: str
    slug: str


class RedeemCodeRequest(BaseModel):
    """Request to redeem a share code."""

    code: str


class RedeemCodeResponse(BaseModel):
    """Response from redeeming a share code."""

    slug: str
    name: str
    already_had_access: bool = Field(default=False, alias="alreadyHadAccess")

    model_config = ConfigDict(populate_by_name=True)


class PublishRequest(BaseModel):
    """Request to publish or manage publish status."""

    slug: str
    custom_message: Optional[str] = Field(default=None, alias="customMessage")

    model_config = ConfigDict(populate_by_name=True)


class PaginationInfo(BaseModel):
    """Pagination metadata."""

    page: int
    limit: int
    total: int
    total_pages: int = Field(..., alias="totalPages")
    has_next: bool = Field(..., alias="hasNext")
    has_prev: bool = Field(..., alias="hasPrev")

    model_config = ConfigDict(populate_by_name=True)


class SkillListResponse(BaseModel):
    """Response from list skills endpoint."""

    data: list[Skill] = Field(default_factory=list)
    pagination: PaginationInfo

    model_config = ConfigDict(populate_by_name=True)
